t.script:
document.getElementById('project_picker_search') && document.getElementById('project_picker_search').addEventListener('input', function () {
    const q = this.value.toLowerCase().trim();
    document.querySelectorAll('.project-pick').forEach(function (el) {
        const name = (el.getAttribute('data-name') || '').toLowerCase();
        el.style.display = (!q || name.indexOf(q) !== -1) ? '' : 'none';
    });
});

(function () {
    var nav = document.getElementById('portal_top_nav');
    var extra = document.getElementById('banner_extra');
    if (nav && extra) {
        nav.style.setProperty('--banner-extra-h', (extra.offsetHeight || 0) + 'px');
    }
})();

document.addEventListener('DOMContentLoaded', function () {
    const targetDateStr = "";
    const isEditable = ;
    const isInternal = ;
    const csrf = "";
    const queueKey = 'ages_portal_queue_' + targetDateStr;
    let saveTimer = null;
    let saving = false;

    (function setupCollapsingBanner() {
        const nav = document.getElementById('portal_top_nav');
        const extra = document.getElementById('banner_extra');
        const toggle = document.getElementById('btn_banner_toggle');
        if (!nav || !extra) return;
        const storageKey = 'ages_portal_banner_collapsed';
        try {
            if (sessionStorage.getItem(storageKey) === '1') {
                nav.classList.add('is-user-collapsed');
            }
        } catch (e) {}

        function extraHeight() {
            return extra.offsetHeight || 0;
        }
        function syncStickyOffset() {
            const next = extraHeight() + 'px';
            if (nav.style.getPropertyValue('--banner-extra-h') !== next) {
                nav.style.setProperty('--banner-extra-h', next);
            }
        }
        function syncToggle() {
            if (!toggle) return;
            const hidden = nav.classList.contains('is-user-collapsed') || nav.classList.contains('is-extra-off');
            toggle.setAttribute('aria-expanded', hidden ? 'false' : 'true');
            toggle.title = hidden ? 'Show full banner' : 'Minimize banner';
            toggle.setAttribute('aria-label', toggle.title);
        }
        if (window.ResizeObserver) {
            new ResizeObserver(syncStickyOffset).observe(extra);
                } else {
            window.addEventListener('resize', syncStickyOffset, { passive: true });
        }
        if (window.IntersectionObserver) {
            new IntersectionObserver(function (entries) {
                const on = entries[0] && entries[0].isIntersecting;
                nav.classList.toggle('is-extra-off', !on);
                syncToggle();
            }, { threshold: 0.05 }).observe(extra);
        }
        if (toggle) {
            toggle.addEventListener('click', function () {
                if (nav.classList.contains('is-user-collapsed')) {
                    nav.classList.remove('is-user-collapsed');
                    try { sessionStorage.setItem(storageKey, '0'); } catch (e) {}
                    syncStickyOffset();
                    syncToggle();
                    return;
                }
                if (nav.classList.contains('is-extra-off')) {
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                    return;
                }
                nav.classList.add('is-user-collapsed');
                try { sessionStorage.setItem(storageKey, '1'); } catch (e) {}
                syncStickyOffset();
                syncToggle();
            });
        }
        syncStickyOffset();
        syncToggle();
    })();

    function toast(message, type) {
        const stack = document.getElementById('toast_stack');
        if (!stack) return;
        const el = document.createElement('div');
        el.className = 'ages-toast ' + (type || 'ok');
        el.textContent = message;
        stack.appendChild(el);
        setTimeout(function () { el.remove(); }, 3200);
    }

    function setAutosaveStatus(text) {
        const el = document.getElementById('autosave_status');
        if (el) el.textContent = text;
    }

    function rpc(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': csrf
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params || {},
                id: Date.now()
            })
        }).then(function (r) { return r.json(); });
    }

    function getCurrentTimeString() {
        const now = new Date();
        return String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');
    }

    function collectRows() {
        const seen = {};
        const rows = [];
        document.querySelectorAll('.attendance-row').forEach(function (row) {
            const id = row.getAttribute('data-record-id');
            if (!id || seen[id]) return;
            seen[id] = true;
            const typeEl = row.querySelector('.work-entry-select');
            rows.push({
                record_id: id,
                check_in: (row.querySelector('.check-in-input') || {}).value || '',
                check_out: (row.querySelector('.check-out-input') || {}).value || '',
                overtime: (row.querySelector('.overtime-input') || {}).value || 0,
                work_entry_type: typeEl ? typeEl.value : ''
            });
        });
        return rows;
    }

    function unmarkedFromDom() {
        return collectRows().filter(function (r) { return !r.work_entry_type; });
    }

    function queueOffline(rows) {
        try {
            localStorage.setItem(queueKey, JSON.stringify({
                date_str: targetDateStr,
                rows: rows,
                ts: Date.now()
            }));
        } catch (e) {}
    }

    function clearOfflineQueue() {
        try { localStorage.removeItem(queueKey); } catch (e) {}
    }

    function saveAll(opts) {
        opts = opts || {};
        const rows = collectRows();
        if (!navigator.onLine) {
            queueOffline(rows);
            setAutosaveStatus('Offline — queued locally');
            if (!opts.silent) toast('Offline. Changes queued and will sync when online.', 'warn');
            return Promise.resolve({ offline: true });
        }
        if (saving) return Promise.resolve({ busy: true });
        saving = true;
        setAutosaveStatus('Saving…');
        return rpc('/project/portal/attendance/save_all', {
            date_str: targetDateStr,
            rows: rows
        }).then(function (res) {
            saving = false;
            const data = (res && res.result) || {};
            if (data.status === 'success') {
                clearOfflineQueue();
                setAutosaveStatus('Saved ' + new Date().toLocaleTimeString());
                if (!opts.silent) toast(data.message || 'Saved', 'ok');
            } else {
                queueOffline(rows);
                setAutosaveStatus('Save failed — queued');
                if (!opts.silent) toast((data && data.message) || 'Save failed', 'err');
            }
            return data;
        }).catch(function () {
            saving = false;
            queueOffline(rows);
            setAutosaveStatus('Offline — queued locally');
            if (!opts.silent) toast('Save failed. Queued locally.', 'err');
            return { status: 'error' };
        });
    }

    function scheduleAutosave() {
        if (!isEditable) return;
        setAutosaveStatus('Unsaved changes…');
        if (saveTimer) clearTimeout(saveTimer);
        saveTimer = setTimeout(function () { saveAll({ silent: true }); }, 1200);
    }

    function flushOfflineQueue() {
        if (!isEditable || !navigator.onLine) return;
        let payload = null;
        try { payload = JSON.parse(localStorage.getItem(queueKey) || 'null'); } catch (e) {}
        if (!payload || !payload.rows) return;
        setAutosaveStatus('Syncing offline queue…');
        rpc('/project/portal/attendance/save_all', {
            date_str: payload.date_str || targetDateStr,
            rows: payload.rows
        }).then(function (res) {
            const data = (res && res.result) || {};
            if (data.status === 'success') {
                clearOfflineQueue();
                setAutosaveStatus('Offline queue synced');
                toast('Offline changes synced.', 'ok');
            }
        });
    }

    // Search
    const searchInput = document.getElementById('employee_search_input');
    if (searchInput) {
        searchInput.addEventListener('input', function () {
            const q = this.value.toLowerCase().trim();
            document.querySelectorAll('.attendance-row').forEach(function (row) {
                const name = (row.querySelector('.emp-name') || {}).textContent || '';
                const job = (row.querySelector('.emp-job') || {}).textContent || '';
                const empType = (row.querySelector('.emp-type') || {}).textContent || '';
                row.style.display = (!q || name.toLowerCase().includes(q) || job.toLowerCase().includes(q) || empType.toLowerCase().includes(q)) ? '' : 'none';
            });
        });
    }

    window.addEventListener('online', flushOfflineQueue);
    flushOfflineQueue();

    // Unconfirm (internal)
    const unconfirmBtn = document.getElementById('btn_unconfirm');
    if (unconfirmBtn) {
        unconfirmBtn.addEventListener('click', function () {
            if (!confirm('Unlock today and allow editing again?')) return;
            unconfirmBtn.disabled = true;
            rpc('/project/portal/attendance/unconfirm', { date_str: targetDateStr }).then(function (res) {
                unconfirmBtn.disabled = false;
                const data = (res && res.result) || {};
                if (data.status === 'success') {
                    toast(data.message || 'Unlocked', 'ok');
                    setTimeout(function () { window.location.reload(); }, 600);
                } else {
                    toast((data && data.message) || 'Unlock failed', 'err');
                }
            }).catch(function () {
                unconfirmBtn.disabled = false;
                toast('Unlock failed', 'err');
            });
        });
    }

    if (!isEditable) return;

    function bindRow(row) {
        const checkInInput = row.querySelector('.check-in-input');
        const checkOutInput = row.querySelector('.check-out-input');
        const overtimeInput = row.querySelector('.overtime-input');
        const selectWorkEntry = row.querySelector('.work-entry-select');
        const setInBtn = row.querySelector('.set-in-btn');
        const setOutBtn = row.querySelector('.set-out-btn');

        function applyAbsentState() {
            const isAbsent = selectWorkEntry && selectWorkEntry.value === 'absent';
            if (checkInInput) checkInInput.disabled = isAbsent;
            if (checkOutInput) checkOutInput.disabled = isAbsent;
            if (setInBtn) setInBtn.disabled = isAbsent;
            if (setOutBtn) setOutBtn.disabled = isAbsent;
            if (isAbsent) {
                if (checkInInput) checkInInput.value = '';
                if (checkOutInput) checkOutInput.value = '';
            }
        }

        [checkInInput, checkOutInput, overtimeInput].forEach(function (input) {
            if (!input) return;
            input.addEventListener('change', function () {
                if ((input === checkInInput || input === checkOutInput) && input.value.trim() && selectWorkEntry && !selectWorkEntry.value) {
                    selectWorkEntry.value = 'attendance';
                }
                scheduleAutosave();
            });
            input.addEventListener('blur', function () { scheduleAutosave(); });
        });
        if (selectWorkEntry) {
            selectWorkEntry.addEventListener('change', function () {
                applyAbsentState();
                scheduleAutosave();
            });
        }
        if (setInBtn) {
            setInBtn.addEventListener('click', function (e) {
                e.preventDefault();
                checkInInput.value = getCurrentTimeString();
                if (selectWorkEntry) selectWorkEntry.value = 'attendance';
                applyAbsentState();
                scheduleAutosave();
            });
        }
        if (setOutBtn) {
            setOutBtn.addEventListener('click', function (e) {
                e.preventDefault();
                checkOutInput.value = getCurrentTimeString();
                if (selectWorkEntry) selectWorkEntry.value = 'attendance';
                applyAbsentState();
                scheduleAutosave();
            });
        }
    }

    document.querySelectorAll('.attendance-row').forEach(bindRow);

    const saveBtn = document.getElementById('btn_save_attendance');
    if (saveBtn) {
        saveBtn.addEventListener('click', function () {
            saveBtn.disabled = true;
            saveAll({ silent: false }).then(function () { saveBtn.disabled = false; });
        });
    }

    function openUnmarkedModal(data) {
                    const modalBody = document.getElementById('unmarked_modal_body');
        const msg = document.getElementById('unmarked_modal_message');
        if (msg && data.message) msg.textContent = data.message;
                    modalBody.innerHTML = '';
        (data.unmarked_employees || []).forEach(function (emp) {
                        const tr = document.createElement('tr');
                        tr.setAttribute('data-record-id', emp.id);
            const tdName = document.createElement('td');
            tdName.className = 'fw-bold';
            tdName.textContent = emp.name || '';
            const tdType = document.createElement('td');
            tdType.textContent = emp.employee_type || '-';
            const tdJob = document.createElement('td');
            tdJob.className = 'text-muted';
            tdJob.textContent = emp.job || '-';
            const tdSel = document.createElement('td');
            tdSel.innerHTML = '<select class="form-select wizard-work-entry"><option value="">— Select —</option><option value="attendance">Attendance</option><option value="absent">Absent</option></select>';
            tr.appendChild(tdName);
            tr.appendChild(tdType);
            tr.appendChild(tdJob);
            tr.appendChild(tdSel);
                        modalBody.appendChild(tr);
                    });
        new bootstrap.Modal(document.getElementById('unmarked_modal')).show();
    }

    const confirmBtn = document.getElementById('btn_confirm_attendance');
    if (confirmBtn) {
        confirmBtn.addEventListener('click', function () {
            const missing = unmarkedFromDom();
            if (missing.length) {
                toast('Cannot confirm: ' + missing.length + ' employee(s) still unmarked.', 'warn');
                openUnmarkedModal({
                    message: 'Cannot confirm until every employee has Attendance or Absent.',
                    unmarked_employees: missing.map(function (r) {
                        const row = document.querySelector('.attendance-row[data-record-id="' + r.record_id + '"]');
                        return {
                            id: r.record_id,
                            name: ((row && row.querySelector('.emp-name')) || {}).textContent || 'Employee',
                            employee_type: ((row && row.querySelector('.emp-type')) || {}).textContent || '',
                            job: ((row && row.querySelector('.emp-job')) || {}).textContent || ''
                        };
                    })
                });
                return;
            }

            confirmBtn.disabled = true;
            saveAll({ silent: true }).then(function () {
                return rpc('/project/portal/attendance/confirm', { date_str: targetDateStr });
            }).then(function (res) {
                confirmBtn.disabled = false;
                const data = (res && res.result) || {};
                if (data.status === 'success' || data.status === 'partial') {
                    toast(data.message || 'Attendance confirmed.', data.status === 'partial' ? 'warn' : 'ok');
                    setTimeout(function () { window.location.reload(); }, 800);
                } else if (data.status === 'unmarked') {
                    toast(data.message || 'Some employees are unmarked.', 'warn');
                    openUnmarkedModal(data);
                } else {
                    toast(data.message || 'Confirm failed.', 'err');
                }
            }).catch(function () {
                confirmBtn.disabled = false;
                toast('Confirm failed. Check connection.', 'err');
            });
        });
    }

    const saveUnmarkedBtn = document.getElementById('btn_save_unmarked_and_confirm');
    if (saveUnmarkedBtn) {
        saveUnmarkedBtn.addEventListener('click', function () {
            const updates = [];
            let incomplete = false;
            document.querySelectorAll('#unmarked_modal_body tr').forEach(function (tr) {
                const wtype = tr.querySelector('.wizard-work-entry').value;
                if (!wtype) incomplete = true;
                updates.push({ record_id: tr.getAttribute('data-record-id'), work_entry_type: wtype });
            });
            if (incomplete) {
                toast('Set a status for every unmarked employee first.', 'warn');
                return;
            }
            saveUnmarkedBtn.disabled = true;
            rpc('/project/portal/attendance/batch_update_unmarked', {
                date_str: targetDateStr,
                updates: updates
            }).then(function (res) {
                saveUnmarkedBtn.disabled = false;
                const data = (res && res.result) || {};
                if (data.status === 'success' || data.status === 'partial') {
                    toast(data.message || 'Attendance confirmed.', data.status === 'partial' ? 'warn' : 'ok');
                    setTimeout(function () { window.location.reload(); }, 700);
                } else {
                    toast(data.message || 'Could not confirm.', 'err');
                }
            }).catch(function () {
                saveUnmarkedBtn.disabled = false;
                toast('Confirm failed.', 'err');
            });
        });
    }
});
